Method.Implementation:
	#dim jmsgateway As EnsLib.JavaGateway.JavaGateway
	#dim ctx As javax.naming.InitialContext
   #dim cf As javax.jms.ConnectionFactory
   #dim connection As  javax.jms.Connection
   #dim session As  javax.jms.Session
   #dim message As javax.jms.Message
   #dim  consumer As javax.jms.MessageConsumer

	set jmsgateway = ""
	set topicConnection = ""
	set topicSubscriber = ""
	set consumer = ""
	set session = ""
	set connection = ""
	set ctx = ""
	Set tStat = $$$OK

	$$$LOGINFO("ITFCOMMON.JMS.ForeSight.InboundAdapter OnTask for " _ ..BusinessHost.%ConfigName _ " in " _$NAMESPACE)


	// get an instance of JMSGateway and connect to JMSGateway Super Server
	try {
		Set jmsgateway=##class(EnsLib.JavaGateway.JavaGateway).%New()
		Set classPath=##class(%ListOfDataTypes).%New()
		$$$LOGINFO("To connect")

		Do classPath.Insert(..JMSJarPath)
		$$$LOGINFO("JMS Call Path added: " _ ..JMSJarPath)

		For n=1:1:$L(..JMSJarPath,":") {
			set jarFile = $P(..JMSJarPath,":",n)
            Do jmsgateway.%Import(jarFile)
            $$$LOGINFO("JMS Call Path added: " _ jarFile)
        }


		Set tStat=jmsgateway.%Connect(..JavaGateWayHost,..JavaGateWayPort,$NAMESPACE,5,classPath) 
		If 'tStat 
		{
			set tStat = $$$ISERR(status)
			set exp = ##class(%Exception.General).%New()
			set exp.Code = status.Name
			set exp.Data = status.Data
			set exp.Name = "Java Gateway connection error"
			Throw exp  
		}
		$$$LOGINFO("Connected to Java Gateway")

		Set tuxHash=##class(java.util.Hashtable).%New(jmsgateway)
        Do tuxHash.put("java.naming.factory.initial", ..InitialFactory )
        Do tuxHash.put("java.naming.provider.url", ..URL)

        $$$LOGINFO( "Created hash")
		// create InitialContext 
        SET ctx = ##class(javax.naming.InitialContext).%New(jmsgateway, tuxHash)
        $$$LOGINFO( "Create initial context " _ ctx)

       Set cf = ctx.lookup(..ConnectionFactoryName)
        $$$LOGINFO( ..ConnectionFactoryName _ " = " _ cf )
          set dest = ctx.lookup(..TopicName)
          $$$LOGINFO( "Dest: " + dest)

          set connection = cf.createConnection()
           if ..DurableConnection '= 0
          {
	         SET localhost=$SYSTEM.INetInfo.LocalHostName()            /* get host name */
             set subNm = $Replace(localhost, ".co.ihc.com", "") _ "_" _ $NAMESPACE _ "_" _ ..BusinessHost.%ConfigName
             $$$LOGINFO("Subscriber name " _ subNm)
             Do connection.setClientID(subNm)
          }
          $$$LOGINFO( "Conn: " _ connection)
          set c1 = 0
          set c2 = 1
          set session = connection.createSession(c1, c2) 
          $$$LOGINFO( "Created session")

          if ..DurableConnection = 0
          {
             Set consumer = session.createConsumer(dest)
          }
          else
          {

	         Set consumer = session.createDurableSubscriber(dest, subNm)
          }
          Do connection.start()

          $$$LOGINFO("Started session")

        $$$LOGINFO("Receive with timeout")
    	 set message = consumer.receive(10000)
        do {


    		if message = ""
    		{
	    		 $$$LOGINFO("No message in the queue")
	    		 Quit 
    		}
   			elseif message.%IsA("javax.jms.TextMessage")
			{
	   			$$$LOGINFO("Got a TextMessage: " _ message.getText())
	   			Set tStat = ..SendMessageToService(message.getText())	   
			}
			elseif message.%IsA("javax.jms.BytesMessage")
			{
				set arrLen = 10000
				set comMsg = ""
				$$$LOGINFO("Got a BytesMessage of length ")
				Set readStream=##class(%GlobalBinaryStream).%New()
        		// reserve a number of bytes since we are passing the stream by reference      
        		For i=1:1:arrLen Do readStream.Write("0")

        		do {            
		    		set bytesRead = message.readBytes(.readStream, arrLen)
		    		set msgText = readStream.Read(bytesRead)
		    		set comMsg = comMsg _ msgText
		  		 	$$$LOGINFO( "byte msg. length " _ bytesRead )
        		} while (bytesRead = arrLen)
		  		$$$LOGINFO("SendMessageToService: " _ $LENGTH(comMsg))
		  		try
		  		{
		  		Set tStat = ..SendMessageToService(comMsg)
		  		} 
		  		catch exp
		  		{
			  		$$$LOGERROR("ERROR in SendMessageToService " _ exp.Data)
			  		throw exp
		  		}		
			}
			$$$LOGINFO("Commit and close")
			Do topicSession.commit()
			//Get next message
			$$$LOGINFO("receive with timeout")
    		set message=consumer.receive(10)
        } while message '= ""


        $$$LOGINFO("connection.stop")
	    Do connection.stop()
	    $$$LOGINFO("connection.close")
		Do connection.close()

	    $$$LOGINFO("session.close")
	    Do session.close()
	    $$$LOGINFO("connection.close")
	    Do connection.close()
	    $$$LOGINFO("ctx.close")
	    Do ctx.close()
	    $$$LOGINFO("Disconnect")
		Do jmsgateway.%Disconnect() 
	 } catch err
     {
	     if $GET(%objlasterror) '= ""
	    {
	        set errMsg =  $System.Status.GetErrorText(%objlasterror)
	    }
	    else
	    {
		    set errMsg = "No obj"
	    }
	    $$$LOGALERT("Exception: Name: " _ err.Name _ " / Location:" _ err.Location _ " / Data: " _err.Data _ " / Details: " _ errMsg)
	    Set tSC=$$$ERROR($$$GeneralError, err.Name _ " / Location:" _ err.Location _ " / Data: " _err.Data _ " " _ errMsg)

	    if (connection '= "")
	    {
	      Do connection.stop()
	      Do connection.close()
	    }
	    if (consumer '= "")
	    {
	       Do consumer.close()
	    }

	    if (session '= "")
	    {
	       Do session.close()
	    }
	    if (ctx '= "")
	    {
	       Do ctx.close()
	    }
	    if (jmsgateway '= "")
	    {
		  	Do jmsgateway.%Disconnect()
	    }
    }

	Quit tStat
